import Foundation
import KwipMLCore

@MainActor enum LayerOverviewLessonCopy {
    struct Overview {let purpose:String;let idea:String;let action:String;let question:String}
    static let overviews:[String:Overview]=[
        "activation":.init(purpose:"A stack of feature-mixing layers needs ways to change which signals pass through. Activations provide those nonlinear responses; Softmax instead compares a group of scores.",idea:"ReLU clips negative values. Leaky ReLU/PReLU retain a fraction of them. Sigmoid and Tanh bound individual values; GELU and SiLU gate them smoothly. Softmax groups scores into shares adding to one; LogSoftmax stores their logarithms. These functions do not all serve the same purpose.",action:ActivationLearningContent.placementInstructions,question:"When should each value change independently, and when should a group of scores compete? Why is a Sigmoid output not automatically a well-calibrated probability?"),
        "pooling-overview":.init(purpose:"A model may need a compact summary of nearby measurements instead of every position. Pooling reduces or reorganizes spatial detail separately within each channel.",idea:"Max keeps a local winner. Average summarizes a region using a sum and a divisor. A fixed window uses configured size/stride; adaptive output chooses regions from your desired output size. A channel is one separate field of measurements, and an observation is one independent example.",action:PoolingLearningContent.placementInstructions,question:"Why can a Max result stay negative? What does an index identify? How does the divisor affect an Average result near a boundary?"),
        "convolution-overview":.init(purpose:"A pattern may appear at several positions. Convolution shares a learned local window across those positions, rather than learning unrelated weights for every location.",idea:"Channels are measurement fields; spatial directions describe positions along a line, map or volume. Kernel size chooses the window, Stride moves it, and Dilation spaces its cells. Standard convolution combines input neighborhoods. Transposed convolution spreads contributions into an output and adds overlap; it does not generally invert the earlier calculation. Depthwise filters channels separately.",action:ConvolutionLearningContent.placementInstructions,question:"Which settings affect spatial size and which affect channel connections? Why can arranging table features as a grid teach the calculation without making those features a real photograph?"),
        "normalization-overview":.init(purpose:"Later layers can be easier to use when related measurements are on a consistent scale. Normalization's grouping decides which values share a summary.",idea:"Layer and RMS work over trailing sample dimensions; RMS does not subtract the mean. Batch compares channels across a current group and can remember summaries. Instance keeps each observation/channel separate. Group compares teams of channels within one observation. Learned scale/shift are parameters, distinct from those measured summaries.",action:NormalizationLearningContent.placementInstructions,question:"How does model normalization differ from Preprocess fitting a Training table? Which method's behavior can change between training and evaluation?"),
        "linear-overview":.init(purpose:"A model often needs to turn several measurements into a new feature list or class scores. Linear mixes the final feature direction using weights and an optional bias offset.",idea:"For each output feature, multiply incoming features by their corresponding weights and add them, then add bias if enabled. The same weight set is reused for every observation. Setting an input width explicitly and inferring it from a connection are two ways to create the same kind of layer; inference does not train it.",action:"Place Linear from Layers. In Configuration, Input sizing chooses Set explicitly or Infer from input. Set Output features and the bias choice; Weights and biases owns the layer's parameter policies. A changed width needs compatible new state; saved weights never resize automatically.",question:"Which numbers are input observations and which numbers can training adjust? Why is a one-time inferred width different from a changing batch size?"),
        "recurrent-overview":.init(purpose:"A sequence has an order: an earlier measurement can help interpret a later one. Recurrent reads the whole sequence while updating an explicit hidden summary.",idea:"RNN updates one hidden state with a response such as Tanh. GRU uses gates to update one state. A gate is a learned choice about how much information to keep. LSTM carries separate hidden and cell memories and can project its hidden output. A sequence's time direction is separate from its feature direction and from the observation count.",action:"Place Recurrent from Layers and select RNN, LSTM or GRU in Method. Configure feature/state widths, layers and starting state. Whole-sequence output and final state are different ports. Learned weights belong to the layer; hidden/cell state travels as tensor data.",question:"How is the final state different from the outputs at every time position? Why should another observation's starting memory not silently enter this one?"),
        "recurrent-cell-overview":.init(purpose:"Sometimes a model needs to define one state update explicitly. Recurrent Cell processes one feature vector and its starting state; it does not secretly loop over a whole sequence.",idea:"RNN Cell and GRU Cell update one hidden state. LSTM Cell updates hidden and cell state separately. Connecting a state output to a later step makes that data movement visible. The cell's learned weights are reused; they are not the state being passed.",action:"Place Recurrent Cell from Layers and choose RNN Cell, LSTM Cell or GRU Cell in Method. Configure the feature and state widths and connect the intended starting-state tensors. Use Recurrent when you want a whole ordered sequence processed by one tool.",question:"What must a later step receive from the previous one? Why is an omitted starting state different from a saved set of learned weights?"),
        "dropout":.init(purpose:"A training model can become overly dependent on one exact collection of features. Dropout temporarily removes some individual measurements during training, while evaluation uses the full signal.",idea:"Drop probability is a chance per value, not a guarantee that an exact percentage disappears. Below probability 1, retained training values scale by 1/(1−p); probability 0 leaves them intact and probability 1 makes training output zero. Evaluation passes values unchanged and draws no removal mask. Shape and learned parameter count do not change.",action:"Use Open Dropout classifier example in Exercise choices & reference to load the runnable graph; save existing work first. Select Dropout and configure Drop probability. Run, inspect its captured tensor, then compare training with evaluation. Runtime, device, seed and call order matter to an exact random pattern.",question:"Why can two training calls remove different positions? Why should the same probability not remove measurements during evaluation? An unchanged output at evaluation is expected, not a broken setting.")
    ]
    static func steps(_ id:String)->[LessonContentStep]? {
        if let copy=overviews[id] {
            return [
                LessonContent.step("goal","Choose the right operation",copy.purpose+"\n\nA fresh overview opens a lesson canvas with no supplied training flow. Exercise choices & reference contains the actual runnable examples and separate Construction assessments. Choose one there when you want to work on the canvas; reading Next never places components."),
                LessonContent.step("build","Understand the alternatives",copy.idea),
                LessonContent.step("overview.controls","Use the current tool",copy.action,kind:.canvasAction),
                LessonContent.step("inspect","Check your understanding",copy.question+"\n\nThis overview is unscored. A runnable example shows captured output after an actual run. A Construction assessment requires its own current passing result and saved receipt.",kind:.question)
            ]
        }
        if id=="spatial-practice" {
            var result=[LessonContent.step("goal","Explore windows and channels", "A model can learn a local pattern or summarize a neighborhood. This Guided exploration compares those choices using constructed numeric features. It does not import photographs, recorded sound or scans.\n\nThe initial canvas is empty. In Exercise choices & reference, choose the matching Open editable example button when a step asks for it. Save work before replacing a graph. Start with Convolution along a line, run its supplied graph unchanged, then compare one explicit setting.")]
            result[0].blocks.append(.init(id:"goal.terms",kind:.detail,title:"Words to know",text:SpatialLearningPracticeContent.terms))
            result.append(LessonContent.step("build","Plan one change",SpatialLearningPracticeContent.runInstruction,kind:.canvasAction))
            result += SpatialLearningPracticeContent.entries.map {entry in
                .init(id:"spatial."+entry.id,title:entry.title,blocks:[
                    .init(id:entry.id+".predict",kind:.question,title:"Predict",text:entry.prediction),
                    .init(id:entry.id+".change",kind:.canvasAction,title:"Change one setting",text:entry.change),
                    .init(id:entry.id+".inspect",kind:.observation,title:"Compare captured output",text:entry.inspection)])
            }
            result.append(LessonContent.step("inspect","Interpret the experiment",SpatialLearningPracticeContent.runInstruction+"\n\nThis is unscored exploration. A new architecture can retrain to different weights; compare the intended geometry change separately from prediction quality.",kind:.observation))
            return result
        }
        if id=="module-composition-examples" {
            return [
                LessonContent.step("goal","Inspect connected reusable Blocks","A reusable Block contains connected calculations. Private copies can reuse its structure while retaining independent learned values. An ordered collection and a sequence can store the same children but describe different organization.\n\nThe initial Example canvas is empty. In Exercise choices & reference, choose a worked example. Its supplied Block model is already connected, so you can inspect structure and state before making changes. Save existing work first."),
                LessonContent.step("build","Trace the supplied model","Open each supplied Block and follow the connections, child order and stored names. Compare private copies without assuming their weights are shared. In an ordinary workflow, Parallel features exposes its container on the main canvas; these advanced mathematical examples retain their dedicated Block editors.",kind:.canvasAction),
                LessonContent.step("example.check","Check the supplied behavior","Choose Check construction to measure the worked example's results, influence, adjustments and saved reuse. This is a Guided example check, not an assessment pass. Inspect the actual measured evidence; reading or saving does not establish correctness.",kind:.canvasAction),
                LessonContent.step("inspect","Explain reuse and order","Which information belongs to the reusable structure, which to a private weight copy, and which to connections? How could stored order differ from the calculation's connected order?\n\nThese worked examples are unscored. Use the separate Construction assessments to submit your own task-specific model.",kind:.question)
            ]
        }
        return nil
    }
    static func workedSteps(_ operation:String)->[LessonContentStep]? {
        guard let task=ModuleCompositionLearningTask(rawValue:operation) else {return nil}
        return [
            LessonContent.step("goal","Inspect the connected worked example","This supplied Block model is already connected for “\(task.title)”. It is a Guided example, not an assessment attempt. Inspect its structure and private copies; learned weights are separate from the tensor values travelling between components."),
            LessonContent.step("build.0","Open each Block","Open the supplied nested editors and trace each connection. Preserve the fixed context. \(task == .buildReuse ? "Compare each private copy's learned settings and its connected use." : "Compare stored child order and names with the connections that define the calculation.")",kind:.canvasAction),
            LessonContent.step("check","Measure the example","Choose Check construction to run the actual example check. Compare the measured result and reuse/state evidence. The guided check can explain a difference but cannot award an assessment completion. Save retains this example's canvas and reading position.",kind:.observation)
        ]
    }
}
